// pricer.cpp  (built into libpricer.so)
#include <cmath>

extern "C" double norm_cdf(double x) {
    return 0.5 * std::erfc(-x / std::sqrt(2.0));   // Phi(x) = erfc identity
}

// loader.cpp
#include <dlfcn.h>
#include <cstdio>

int main() {
    void* lib = dlopen("./libpricer.so", RTLD_NOW);
    if (!lib) { std::printf("dlopen: %s\n", dlerror()); return 1; }

    using NormCdf = double (*)(double);
    auto norm_cdf = reinterpret_cast<NormCdf>(dlsym(lib, "norm_cdf"));
    if (!norm_cdf) { std::printf("dlsym: %s\n", dlerror()); return 1; }

    std::printf("N(0.25) = %.4f\n", norm_cdf(0.25));
    dlclose(lib);
}

